arguments.command:
python3 - <<'EOF'
with open('genealogy_trees.txt', encoding='utf-8') as f:
    lines = [l.rstrip('\n') for l in f.readlines()]

def marks(r):
    if r<0 or r>=len(lines): return {}
    line = lines[r]
    return {idx:ch for idx, ch in enumerate(line) if ch in '+|│'}

import re
def runs(r):
    line = lines[r]
    out = []
    for m in re.finditer(r'[-~+]+', line):
        if '+' in m.group():
            out.append((m.start(), m.end()))
    return out

r = 51
rs = runs(r)
above = marks(r-1)
below = marks(r+1)
for (s,e) in rs:
    plus_cols = [c for c in range(s,e) if lines[r][c]=='+']
    up = [c for c in plus_cols if c in above]
    down = [c for c in plus_cols if c in below]
    if e-s > 3:
        print((s,e), 'plus:',plus_cols, 'up:',up,'down:',down)
EOF

